INSERT OR REPLACE INTO question_sets(id,title,language,level,topic,context,skill,description,is_official,visibility,status,version,created_by,created_at,updated_at) VALUES ('official-en-school-scenario','English — School & Classroom Scenarios','en','School / Intermediate','School & Classroom','School Workplace','Dialogue / Reading / Scenario','Bài tập thực tế ở trường: đổi lịch, đổi phòng, thông báo, phối hợp và xử lý tình huống lớp học.',1,'public','published',1,NULL,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-s1','official-en-school-scenario','dialogue','Bạn chưa nghe rõ hướng dẫn. Chọn cách yêu cầu nhắc lại lịch sự nhất.','["Could you repeat that, please?","Không cần nói gì.","Nói thật to một từ bất kỳ.","Rời cuộc trò chuyện."]','["Could you repeat that, please?"]','[]','','','','','','','',0,1,'','',2,'["school","dialogue","politeness"]',0,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-s2','official-en-school-scenario','scenario_decision','Bạn đến trường nhưng không tìm thấy phòng học mới. Nên làm gì trước?','["Kiểm tra thông báo và hỏi đầu mối phụ trách","Tự chọn một phòng bất kỳ","Về nhà ngay","Đợi mà không báo ai"]','["Kiểm tra thông báo và hỏi đầu mối phụ trách"]','[]','','','','','','','',0,1,'','',3,'["school-workplace","scenario"]',1,'2026-09-11','2026-09-11');
