INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-professional-x09','official-en-professional','fill_blank','Hoàn thành ý phù hợp trong ngữ cảnh Workplace & School: “Thông báo về lịch hoặc nhiệm vụ” tương ứng với ___.','["Thông báo về lịch hoặc nhiệm vụ","Một câu chuyện cổ tích","Mô tả thời tiết","Quảng cáo trò chơi"]','["Thông báo về lịch hoặc nhiệm vụ"]','[]','Trong bộ bài English, “Thông báo về lịch hoặc nhiệm vụ” được dùng với nghĩa/ý phù hợp là “Thông báo về lịch hoặc nhiệm vụ”.','Dựa vào ngữ cảnh của cụm từ.','','','','','',0,1,'','',2,'["reinforcement","fill-blank","workplace-&-school"]',8,'2026-09-11','2026-09-11');
