INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-foundation-x23','official-ar-foundation','error_correction','Chọn cách giao tiếp phù hợp hơn trong tình huống cần làm rõ thông tin.','["Bạn có thể xác nhận lại thời gian và yêu cầu giúp tôi không?","Tôi đoán là vậy nên làm luôn.","Không cần nói gì.","Sai thì tính sau."]','["Bạn có thể xác nhận lại thời gian và yêu cầu giúp tôi không?"]','[]','Câu hỏi làm rõ trực tiếp và lịch sự giúp tránh hiểu nhầm.','','','','','','',0,1,'','',4,'["error-correction","pragmatics","professional"]',22,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-foundation-x24','official-ar-foundation','multiple_choice','Khi áp dụng nội dung của “العربية — Foundation & Everyday” vào thực tế, mục tiêu quan trọng nhất là gì?','["Hiểu ý, dùng đúng ngữ cảnh và phản hồi phù hợp","Chỉ ghi nhớ đáp án của một lần chơi","Trả lời càng nhanh càng tốt dù chưa hiểu","Bỏ qua phần giải thích"]','["Hiểu ý, dùng đúng ngữ cảnh và phản hồi phù hợp"]','[]','Sky First Games ưu tiên khả năng sử dụng ngôn ngữ trong tình huống thực tế, không chỉ ghi nhớ đáp án.','','','','','','',0,1,'','',4,'["mastery","real-life","reflection"]',23,'2026-09-11','2026-09-11');
