INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('zh-extra-33-x23','official-zh-extra-33','error_correction','Chọn cách giao tiếp phù hợp hơn trong tình huống cần làm rõ thông tin.','["Bạn có thể xác nhận lại thời gian và yêu cầu giúp tôi không?","Tôi đoán là vậy nên làm luôn.","Không cần nói gì.","Sai thì tính sau."]','["Bạn có thể xác nhận lại thời gian và yêu cầu giúp tôi không?"]','[]','Câu hỏi làm rõ trực tiếp và lịch sự giúp tránh hiểu nhầm.','','','','','','',0,1,'','',4,'["error-correction","pragmatics","professional"]',22,'2026-09-11','2026-09-11');
