INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ko-school-scenario-x09','official-ko-school-scenario','fill_blank','Hoàn thành ý phù hợp trong ngữ cảnh School Workplace: “교실 번호를 확인해 주세요.” tương ứng với ___.','["다시 말씀해 주세요.","Không cần nói gì.","Nói thật to một từ bất kỳ.","Rời cuộc trò chuyện."]','["다시 말씀해 주세요."]','[]','Trong bộ bài 한국어, “교실 번호를 확인해 주세요.” được dùng với nghĩa/ý phù hợp là “다시 말씀해 주세요.”.','Dựa vào ngữ cảnh của cụm từ.','','','','','',0,1,'','',2,'["reinforcement","fill-blank","school-workplace"]',8,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ko-school-scenario-x10','official-ko-school-scenario','multiple_select','Chọn HAI hành động phù hợp khi giao tiếp trong bối cảnh School Workplace.','["Xác nhận lại thông tin quan trọng","Phản hồi rõ ràng và lịch sự","Bỏ qua yêu cầu mà không trả lời","Đoán thông tin còn thiếu rồi làm ngay"]','["Xác nhận lại thông tin quan trọng","Phản hồi rõ ràng và lịch sự"]','[]','Giao tiếp hiệu quả cần xác nhận thông tin và phản hồi rõ ràng.','','','','','','',0,1,'','',3,'["scenario","multiple-select","communication"]',9,'2026-09-11','2026-09-11');
